{"path": "/app/ars.R", "content": "# Adaptive Rejection Sampling (Gilks & Wild, 1992)

.ars_eval_fun <- function(fun, x, ...) {
  val <- tryCatch(fun(x, ...), error = function(e) NULL)
  if (is.null(val) || length(val) != length(x)) {
    val <- sapply(x, function(xi) fun(xi, ...))
  }
  as.numeric(val)
}

.ars_as_function <- function(f) {
  if (is.function(f)) {
    return(f)
  }
  if (is.character(f)) {
    expr <- parse(text = f)[[1]]
  } else if (is.expression(f)) {
    expr <- f[[1]]
  } else if (is.language(f)) {
    expr <- f
  } else {
    stop("f must be a function or expression.")
  }
  function(x, ...) {
    eval(expr, envir = list(x = x, ...), enclos = parent.frame())
  }
}

.ars_make_logf <- function(f, log, ...) {
  f <- .ars_as_function(f)
  if (isTRUE(log)) {
    function(x) {
      vals <- .ars_eval_fun(f, x, ...)
      if (any(is.na(vals))) {
        stop("log-density returned NA.")
      }
      vals
    }
  } else {
    function(x) {
      vals <- .ars_eval_fun(f, x, ...)
      if (any(is.na(vals))) {
        stop("density returned NA.")
      }
      if (any(vals < 0)) {
        stop("density returned negative values.")
      }
      log(vals)
    }
  }
}

.ars_numeric_dlogf <- function(logf, x, domain) {
  x <- as.numeric(x)
  h <- 1e-4 * (1 + abs(x))
  left <- x - h
  right <- x + h
  if (is.finite(domain[1])) {
    left <- pmax(left, domain[1])
  }
  if (is.finite(domain[2])) {
    right <- pmin(right, domain[2])
  }
  out <- numeric(length(x))
  for (i in seq_along(x)) {
    if (left[i] == x[i] && right[i] == x[i]) {
      out[i] <- NA_real_
    } else if (left[i] == x[i]) {
      f0 <- logf(x[i])
      f1 <- logf(right[i])
      out[i] <- (f1 - f0) / (right[i] - x[i])
    } else if (right[i] == x[i]) {
      f0 <- logf(x[i])
      f1 <- logf(left[i])
      out[i] <- (f0 - f1) / (x[i] - left[i])
    } else {
      f1 <- logf(right[i])
      f2 <- logf(left[i])
      out[i] <- (f1 - f2) / (right[i] - left[i])
    }
  }
  out
}

.ars_make_dlogf <- function(dlogf, logf, domain, ...) {
  if (is.null(dlogf)) {
    function(x) .ars_numeric_dlogf(logf, x, domain)
  } else {
    dlogf <- .ars_as_function(dlogf)
    function(x) {
      vals <- .ars_eval_fun(dlogf, x, ...)
      if (any(is.na(vals))) {
        stop("log-derivative returned NA.")
      }
      vals
    }
  }
}

.ars_validate_inputs <- function(n, f, domain, x0, log, dlogf) {
  if (!is.numeric(n) || length(n) != 1 || is.na(n) || n <= 0) {
    stop("n must be a positive integer.")
  }
  n <- as.integer(n)
  if (n <= 0) {
    stop("n must be a positive integer.")
  }
  if (!is.numeric(domain) || length(domain) != 2 || any(is.na(domain))) {
    stop("domain must be a numeric vector of length 2.")
  }
  if (domain[1] >= domain[2]) {
    stop("domain lower bound must be less than upper bound.")
  }
  if (!is.null(x0) && (!is.numeric(x0) || any(is.na(x0)))) {
    stop("x0 must be numeric.")
  }
  if (!is.null(dlogf) && !is.function(dlogf) && !is.character(dlogf) && !is.expression(dlogf) && !is.language(dlogf)) {
    stop("dlogf must be a function or expression when provided.")
  }
  if (!is.function(f) && !is.character(f) && !is.expression(f) && !is.language(f)) {
    stop("f must be a function or expression.")
  }
  list(n = n, f = f, domain = domain, x0 = x0, log = log, dlogf = dlogf)
}

.ars_choose_initial <- function(logf, dlogf, domain) {
  candidates <- numeric(0)
  if (is.finite(domain[1]) && is.finite(domain[2])) {
    candidates <- seq(domain[1], domain[2], length.out = 5)
  } else {
    base <- c(0, -1, 1, -2, 2, -4, 4, -8, 8)
    candidates <- sort(unique(base))
    if (is.finite(domain[1])) {
      candidates <- candidates[candidates > domain[1]]
    }
    if (is.finite(domain[2])) {
      candidates <- candidates[candidates < domain[2]]
    }
  }
  h <- logf(candidates)
  hp <- dlogf(candidates)
  valid <- is.finite(h) & is.finite(hp)
  cand <- candidates[valid]
  iter <- 0
  step <- 8
  while (length(cand) < 3 && iter < 20) {
    step <- step * 2
    new <- c(-step, step)
    if (is.finite(domain[1])) {
      new <- new[new > domain[1]]
    }
    if (is.finite(domain[2])) {
      new <- new[new < domain[2]]
    }
    candidates <- sort(unique(c(candidates, new)))
    h <- logf(candidates)
    hp <- dlogf(candidates)
    valid <- is.finite(h) & is.finite(hp)
    cand <- candidates[valid]
    iter <- iter + 1
  }
  if (length(cand) < 3) {
    stop("Unable to find initial support points; provide x0.")
  }
  sort(cand[1:3])
}

.ars_check_log_concave <- function(x, hprime, tol = 1e-8) {
  if (any(!is.finite(hprime))) {
    stop("Non-finite derivative encountered.")
  }
  if (any(diff(hprime) > tol)) {
    stop("Log-density is not concave (derivative not decreasing).")
  }
  invisible(TRUE)
}

.ars_segment_area <- function(h, hp, x, a, b) {
  if (!is.finite(hp)) {
    stop("Non-finite slope in upper hull.")
  }
  if (abs(hp) < 1e-12) {
    if (!is.finite(a) || !is.finite(b)) {
      stop("Flat hull on infinite interval is not integrable.")
    }
    return(exp(h) * (b - a))
  }
  c0 <- h - hp * x
  if (is.infinite(b)) {
    if (hp >= 0) {
      stop("Right tail not integrable; check log-concavity or domain.")
    }
    return(exp(c0 + hp * a) / (-hp))
  }
  if (is.infinite(a)) {
    if (hp <= 0) {
      stop("Left tail not integrable; check log-concavity or domain.")
    }
    return(exp(c0 + hp * b) / hp)
  }
  log_expa <- hp * a
  log_expb <- hp * b
  m <- max(log_expa, log_expb)
  diff <- exp(log_expb - m) - exp(log_expa - m)
  area <- exp(c0 + m) * diff / hp
  area
}

.ars_build_hull <- function(x, h, hprime, domain) {
  m <- length(x)
  if (is.infinite(domain[1]) && hprime[1] <= 0) {
    stop("Left tail not integrable for infinite domain.")
  }
  if (is.infinite(domain[2]) && hprime[m] >= 0) {
    stop("Right tail not integrable for infinite domain.")
  }
  z <- numeric(m + 1)
  z[1] <- domain[1]
  z[m + 1] <- domain[2]
  if (m > 1) {
    for (i in 1:(m - 1)) {
      denom <- hprime[i] - hprime[i + 1]
      if (abs(denom) < 1e-12) {
        stop("Non-log-concave density: adjacent slopes equal.")
      }
      z[i + 1] <- (h[i + 1] - h[i] - x[i + 1] * hprime[i + 1] + x[i] * hprime[i]) / denom
    }
  }
  if (any(diff(z) <= 0)) {
    stop("Non-log-concave density: intersection points not increasing.")
  }
  areas <- numeric(m)
  for (i in 1:m) {
    areas[i] <- .ars_segment_area(h[i], hprime[i], x[i], z[i], z[i + 1])
  }
  if (any(!is.finite(areas)) || any(areas <= 0)) {
    stop("Invalid upper hull areas.")
  }
  list(z = z, areas = areas)
}

.ars_sample_segment <- function(a, b, hp) {
  if (abs(hp) < 1e-12) {
    if (!is.finite(a) || !is.finite(b)) {
      stop("Cannot sample uniform on infinite interval.")
    }
    return(runif(1, min = a, max = b))
  }
  if (is.infinite(a) && is.infinite(b)) {
    stop("Infinite interval not allowed.")
  }
  if (is.infinite(b)) {
    if (hp >= 0) {
      stop("Right tail not integrable.")
    }
    return(a + rexp(1, rate = -hp))
  }
  if (is.infinite(a)) {
    if (hp <= 0) {
      stop("Left tail not integrable.")
    }
    return(b - rexp(1, rate = hp))
  }
  u <- runif(1)
  log_expa <- hp * a
  log_expb <- hp * b
  m <- max(log_expa, log_expb)
  expa <- exp(log_expa - m)
  expb <- exp(log_expb - m)
  val <- expa + u * (expb - expa)
  (log(val) + m) / hp
}

.ars_sample_upper <- function(support, hull) {
  weights <- hull$areas / sum(hull$areas)
  idx <- sample.int(length(weights), 1, prob = weights)
  a <- hull$z[idx]
  b <- hull$z[idx + 1]
  hp <- support$hprime[idx]
  x <- .ars_sample_segment(a, b, hp)
  u <- support$h[idx] + hp * (x - support$x[idx])
  list(x = x, u = u, idx = idx)
}

.ars_update_support <- function(support, x_new, logf, dlogf) {
  if (any(abs(support$x - x_new) < 1e-12)) {
    return(support)
  }
  h_new <- logf(x_new)
  if (!is.finite(h_new)) {
    stop("Log-density not finite at new support point.")
  }
  hp_new <- dlogf(x_new)
  if (!is.finite(hp_new)) {
    stop("Log-derivative not finite at new support point.")
  }
  x <- c(support$x, x_new)
  h <- c(support$h, h_new)
  hp <- c(support$hprime, hp_new)
  ord <- order(x)
  x <- x[ord]
  h <- h[ord]
  hp <- hp[ord]
  .ars_check_log_concave(x, hp)
  list(x = x, h = h, hprime = hp)
}

ars <- function(n, f, domain = c(-Inf, Inf), x0 = NULL, log = FALSE,
                dlogf = NULL, max_iter = 100000, ...) {
  inputs <- .ars_validate_inputs(n, f, domain, x0, log, dlogf)
  n <- inputs$n
  domain <- inputs$domain
  logf <- .ars_make_logf(inputs$f, inputs$log, ...)
  dlogf_fun <- .ars_make_dlogf(inputs$dlogf, logf, domain, ...)

  if (is.null(inputs$x0)) {
    x0 <- .ars_choose_initial(logf, dlogf_fun, domain)
  } else {
    x0 <- sort(unique(as.numeric(inputs$x0)))
  }
  if (length(x0) < 3) {
    stop("Provide at least 3 initial points in x0.")
  }
  if (any(is.finite(domain[1]) & x0 <= domain[1]) || any(is.finite(domain[2]) & x0 >= domain[2])) {
    stop("Initial points must lie strictly within the domain.")
  }

  h <- logf(x0)
  if (any(!is.finite(h))) {
    stop("Initial log-density values must be finite.")
  }
  hp <- dlogf_fun(x0)
  if (any(!is.finite(hp))) {
    stop("Initial log-derivative values must be finite.")
  }

  support <- list(x = x0, h = h, hprime = hp)
  .ars_check_log_concave(support$x, support$hprime)

  samples <- numeric(n)
  accepted <- 0
  iter <- 0

  while (accepted < n) {
    iter <- iter + 1
    if (iter > max_iter) {
      stop("Maximum iterations exceeded.")
    }
    hull <- .ars_build_hull(support$x, support$h, support$hprime, domain)
    cand <- .ars_sample_upper(support, hull)
    x_star <- cand$x
    u_star <- cand$u

    logf_star <- logf(x_star)
    if (!is.finite(logf_star)) {
      stop("Log-density not finite at proposed sample.")
    }
    if (logf_star > u_star + 1e-6) {
      stop("Log-density exceeds upper hull; distribution not log-concave.")
    }
    if (log(runif(1)) <= logf_star - u_star) {
      accepted <- accepted + 1
      samples[accepted] <- x_star
    } else {
      support <- .ars_update_support(support, x_star, logf, dlogf_fun)
    }
  }
  samples
}

.test_report <- function(name, pass, mean_val = NA, sd_val = NA) {
  status <- if (pass) "PASS" else "FAIL"
  msg <- sprintf("%s: %s mean=%.4f sd=%.4f", name, status, mean_val, sd_val)
  cat(msg, "\n")
}

test <- function() {
  set.seed(123)

  # Test 1: Normal distribution
  normal_logf <- function(x) dnorm(x, mean = 0, sd = 1, log = TRUE)
  normal_dlogf <- function(x) -x
  normal_samples <- ars(5000, normal_logf, log = TRUE, dlogf = normal_dlogf, x0 = c(-1, 0, 1))
  normal_mean <- mean(normal_samples)
  normal_sd <- sd(normal_samples)
  normal_pass <- abs(normal_mean - 0) < 0.05 && abs(normal_sd - 1) < 0.05
  .test_report("NORMAL", normal_pass, normal_mean, normal_sd)

  # Save samples to file
  write.table(normal_samples, file = "/app/normal_samples.txt", row.names = FALSE, col.names = FALSE)

  # Test 2: Exponential distribution
  exp_logf <- function(x) ifelse(x < 0, -Inf, dexp(x, rate = 1, log = TRUE))
  exp_dlogf <- function(x) rep(-1, length(x))
  exp_samples <- ars(5000, exp_logf, log = TRUE, dlogf = exp_dlogf, domain = c(0, Inf), x0 = c(0.2, 1, 3))
  exp_mean <- mean(exp_samples)
  exp_sd <- sd(exp_samples)
  exp_pass <- abs(exp_mean - 1) < 0.05 && abs(exp_sd - 1) < 0.05
  .test_report("EXPONENTIAL", exp_pass, exp_mean, exp_sd)

  # Test 3: Non-log-concave detection
  non_logf <- function(x) log(0.5 * dnorm(x, -2, 1) + 0.5 * dnorm(x, 2, 1))
  non_pass <- FALSE
  non_result <- tryCatch({
    ars(200, non_logf, log = TRUE, x0 = c(-3, 0, 3))
    FALSE
  }, error = function(e) {
    TRUE
  })
  non_pass <- isTRUE(non_result)
  .test_report("NON_LOG_CONCAVE", non_pass, NA, NA)

  # Test 4: Segment area calculation
  area_val <- .ars_segment_area(h = 0, hp = 0, x = 0, a = 0, b = 2)
  area_pass <- abs(area_val - 2) < 1e-6
  .test_report("SEGMENT_AREA", area_pass, NA, NA)

  invisible(list(
    normal = normal_samples,
    exponential = exp_samples
  ))
}
"}

